from pathlib import Path
from collections import Counter,defaultdict
import numpy as np, h5py, scipy.io as sio

def decode_h5(f, obj):
    if isinstance(obj, h5py.Reference):
        obj = f[obj]
    if isinstance(obj, h5py.Group):
        return {k: decode_h5(f, obj[k]) for k in obj.keys()}
    arr = obj[()]
    if obj.dtype == h5py.ref_dtype:
        vals = [decode_h5(f, r) for r in arr.reshape(-1)]
        return vals if arr.size != 1 else vals[0]
    if obj.dtype == np.uint16:
        return ''.join(chr(int(c)) for c in arr.reshape(-1) if c)
    out = np.array(arr).squeeze()
    return out.item() if getattr(out, 'size', 1) == 1 else out

loc_counter=Counter()
probe_count_counter=Counter()
examples=[]
for fn in sorted(Path('data').glob('*/*.mat')):
    if not fn.name.startswith('data_structure_'):
        continue
    try:
        with h5py.File(fn,'r') as f:
            if 'clu' not in f['obj']:
                continue
            locs=decode_h5(f, f['obj/ex/probe/loc'])
            if isinstance(locs, str):
                locs=[locs]
            probe_count_counter[len(locs)] += 1
            for loc in locs:
                loc_counter[str(loc)] += 1
            examples.append((fn.name, locs))
    except OSError:
        obj=sio.loadmat(fn, squeeze_me=True, struct_as_record=False)['obj']
        if not hasattr(obj,'clu'):
            continue
        probe=obj.ex.probe
        if isinstance(probe, np.ndarray) and probe.dtype == object:
            probes=list(probe.reshape(-1))
        elif isinstance(probe, np.ndarray) and getattr(probe, 'shape', ()) == ():
            probes=[probe.item()]
        else:
            probes=[probe]
        locs=[]
        for p in probes:
            loc = getattr(p, 'loc', None)
            if isinstance(loc, np.ndarray):
                loc = ''.join(str(x) for x in loc.tolist()) if loc.dtype.kind in {'U','S'} else str(loc)
            locs.append(str(loc))
        probe_count_counter[len(locs)] += 1
        for loc in locs:
            loc_counter[loc] += 1
        examples.append((fn.name, locs))
print('probe_count_counter', dict(probe_count_counter))
print('location_counter', dict(loc_counter))
print('examples', examples[:15])
