{"cmd":"python3 - <<'PY'
from pathlib import Path
import re
root=Path('code/DataLoadingScripts/Recording and video')
counts={}
entries=[]
for fn in sorted(root.glob('load*_ALMVideo.m')):
    text=fn.read_text()
    active=[]
    for line in text.splitlines():
        s=line.strip()
        if s.startswith('%'):
            continue
        m=re.search(r"date = '([0-9-]+)'", s)
        if m:
            active.append(m.group(1))
    counts[fn.name]=len(active)
    animal=fn.name.split('_')[0].replace('load','')
    if active:
        entries.append((animal,len(active),active))
print('total active sessions', sum(counts.values()))
for animal,n,dates in entries:
    print(animal,n,dates)
PY","workdir":"/app","yield_time_ms":1000,"max_output_tokens":6000}

