import h5py, numpy as np

def decode(f, obj):
    if isinstance(obj, h5py.Reference):
        obj=f[obj]
    if isinstance(obj, h5py.Group):
        return {k: decode(f, obj[k]) for k in obj.keys()}
    arr=obj[()]
    if obj.dtype==h5py.ref_dtype:
        vals=[decode(f,r) for r in arr.reshape(-1)]
        return vals if arr.size!=1 else vals[0]
    if obj.dtype==np.uint16:
        return ''.join(chr(int(c)) for c in arr.reshape(-1) if c)
    out=np.array(arr).squeeze()
    return out.item() if getattr(out,'size',1)==1 else out

